/* global GlideRecord */
/* eslint no-undef: "error" */
(function(outputs, steps, params, stepResult, assertEqual) {

	const EXT_NAME = 'x_itx_codesearch.classic_studio_fix';
	const extPointGr = new GlideRecord('sys_client_extension_point');
	extPointGr.addQuery('api_name', EXT_NAME);
	extPointGr.setLimit(1);
	extPointGr.query();
	if (!extPointGr.next()) {
		stepResult.setOutputMessage(`No Extension Point with name '${EXT_NAME}' found`);
		return false;
	}


	const extGr = new GlideRecord('sys_client_extension_instance');
	extGr.addQuery('point', extPointGr.api_name);
	extGr.addQuery('active', true);
	extGr.addQuery('ui_script.global', true);
	extGr.setLimit(1);
	extGr.query();
	if (!extGr.next()) {
		stepResult.setOutputMessage(`No global Extension Point Implementation for '${extPointGr.api_name}' found`);
		return false;
	}

	if (extGr.ui_script.script != extPointGr.example) {
		stepResult.setOutputMessage(`Extension Point Implementation for ${extPointGr.api_name} uses an outdated script`);
		return false;
	}

	return true;

})(outputs, steps, params, stepResult, assertEqual); /* global outputs, steps, params, stepResult, assertEqual */
